// Only forward strings that look like DCN packets (start with /)
var raw;
if (Buffer.isBuffer(msg.payload)) {
    raw = msg.payload.toString('ascii').trim();
} else {
    raw = String(msg.payload).trim();
}
if (raw.startsWith('/')) {
    msg.payload = raw + '\r';
    return msg;
}
return null;

// DCN packets must end with carriage return (ASCII 13)
var raw;
if (Buffer.isBuffer(msg.payload)) {
    raw = msg.payload.toString('ascii');
} else {
    raw = String(msg.payload);
}
raw = raw.trimEnd();
if (!raw.endsWith('\r')) {
    raw = raw + '\r';
}
msg.payload = Buffer.from(raw, 'ascii');
return msg;
